record.field:

{
  "mappings": {
    "properties": {
      "dimensional_uom_id": {
        "properties": {
          "name": {
            "type": "keyword"
          },
          "id": {
            "type": "integer"
          }
        }
      },
      "supplier_id": {
        "type": "keyword"
      },
      "supplier_promotion": {
        "type": "nested"
      },
      "redirect_url_key": {
        "type": "keyword"
      },
      "packaging_ids": {
        "type": "keyword"
      },
      "hierarchicalCategories": {
        "type": "nested",
        "properties": {
          "ancestors": {
            "type": "keyword"
          },
          "order": {
            "type": "integer"
          },
          "value": {
            "type": "keyword"
          },
          "level": {
            "type": "integer"
          }
        }
      },
      "supplier_discount": {
        "type": "nested"
      },
      "storage_temperature_id": {
        "properties": {
          "name": {
            "type": "keyword"
          },
          "id": {
            "type": "integer"
          }
        }
      },
      "attributes": {
        "properties": {
          "species_id": {
            "type": "keyword"
          },
          "presentation_option_id": {
            "type": "keyword"
          },
          "active_principle_option_ids": {
            "type": "keyword"
          },
          "species_ids": {
            "type": "keyword"
          },
          "administration_route_option_ids": {
            "type": "keyword"
          },
          "categ_age_option_ids": {
            "type": "keyword"
          },
          "indication_option_ids": {
            "type": "keyword"
          },
          "taxes_id": {
            "type": "keyword"
          },
          "product_color_option_ids": {
            "type": "keyword"
          },
          "animal_size_option_ids": {
            "type": "keyword"
          },
          "food_range_option_id": {
            "type": "keyword"
          }
        }
      },
      "main": {
        "type": "boolean"
      },
      "url_key": {
        "type": "keyword"
      },
      "id": {
        "type": "integer"
      },
      "categories": {
        "type": "nested"
      },
      "stock": {
        "properties": {
          "global": {
            "properties": {
              "state": {
                "type": "keyword"
              }
            }
          }
        }
      }
    }
  },
  "settings": {
    "analysis": {
      "filter": {
        "word_delimiter": {
          "catenate_all": true,
          "catenate_numbers": true,
          "generate_word_parts": true,
          "split_on_numerics": false,
          "generate_number_parts": true,
          "preserve_original": true,
          "type": "word_delimiter",
          "split_on_case_change": true
        }
      },
      "index": {
        "sort.order": [
          "desc",
          "asc"
        ],
        "sort.field": [
          "main",
          "id"
        ]
      },
      "char_filter": {
        "replace": {
          "type": "mapping",
          "mappings": [
            "&=> and "
          ]
        }
      },
      "analyzer": {
        "default": {
          "filter": [
            "lowercase",
            "word_delimiter"
          ],
          "char_filter": [
            "html_strip",
            "replace"
          ],
          "type": "custom",
          "tokenizer": "whitespace"
        }
      }
    }
  }
}
